static void add(int from, int to, int num, long[] v, int n) {
    if (from <= to) {
        for (int i = from; i <= to; i++) {
            v[i] += num;
        }
    } else {
        for (int i = from; i < n; i++) {
            v[i] += num;
        }
        for (int i = 0; i <= to; i++) {
            v[i] += num;
        }
    }
}
